package cn.local.gaokao;
import java.util.*;
public final class FsrsTrainerCheck {
 static int checks;static void check(boolean v,String message){if(!v)throw new AssertionError(message);checks++;}
 static FsrsTrainer.Data data(){ArrayList<FsrsTrainer.History> histories=new ArrayList<>();Random random=new Random(17);double[] w=Fsrs.defaultWeights();w[0]*=.4;w[1]*=.4;w[2]*=.4;w[3]*=.4;w[8]*=.2;Fsrs.Model truth=new Fsrs.Model(w);int order=0;for(int n=0;n<60;n++){FsrsTrainer.History h=new FsrsTrainer.History("card"+n,null,0);Fsrs.Memory memory=null;long day=0;for(int r=0;r<12;r++){int elapsed=r==0?0:1+random.nextInt(15),grade=memory==null?3:random.nextDouble()<truth.retrievability(memory,elapsed)?(random.nextBoolean()?3:4):1;day+=elapsed;h.reviews.add(new FsrsTrainer.Review(h.id,day,grade,(int)day*100+n));memory=truth.next(memory,elapsed,grade);order++;}histories.add(h);}return new FsrsTrainer.Data(histories);}
 public static void main(String[] args){FsrsTrainer.Data data=data();check(data.total==660&&data.sufficient(),"cross-day sequence sample counts");double[] before=Fsrs.defaultWeights();FsrsTrainer.Result result=FsrsTrainer.train(data,before,null);check(result.weights.length==21,"twenty-one weights fitted");check(result.trainingAfter<result.trainingBefore,"training loss improves on independent synthetic outcomes");check(result.validationAfter<result.validationBefore&&result.usable,"chronological holdout improves too");check(Arrays.equals(before,Fsrs.defaultWeights()),"fitting never mutates default weights");for(int n=0;n<21;n++)check(result.weights[n]>=Fsrs.LOWER[n]&&result.weights[n]<=Fsrs.UPPER[n],"bounded weight "+n);boolean invalid=false;double[] bad=before.clone();bad[20]=Double.NaN;try{new Fsrs.Model(bad);}catch(IllegalArgumentException e){invalid=true;}check(invalid,"rejects nonfinite weights");FsrsTrainer.Data empty=new FsrsTrainer.Data(Collections.emptyList());check(!empty.sufficient(),"empty history keeps defaults");boolean refused=false;try{FsrsTrainer.train(empty,before,null);}catch(IllegalArgumentException e){refused=true;}check(refused,"insufficient data does not train");check(!new FsrsTrainer.Result(before,.5,.4,.3,.4,.3).usable,"rejects validation regression despite better training loss");check(!new FsrsTrainer.Result(before,.5,.4,.5,.4,.3).usable,"rejects candidate worse than defaults");Thread.currentThread().interrupt();boolean cancelled=false;try{FsrsTrainer.train(data,before,null);}catch(java.util.concurrent.CancellationException e){cancelled=true;}finally{Thread.interrupted();}check(cancelled,"cancel stops training");System.out.println("PASS "+checks+" personal-training math checks; train log loss "+result.trainingBefore+" -> "+result.trainingAfter+", holdout "+result.validationBefore+" -> "+result.validationAfter);}
}
